 const [choices,setChoices]=useState<Record<string,{stream:Stream;sampleIds:string[];selected:boolean}>>({});const titles=addition&&o.additions.some(a=>a.id===addition)?[o.additions.find(a=>a.id===addition)!.title]:[];
