export function ActivityList({job,actor,run}:{job:JobRecord;actor:Actor;run:(c:Command)=>boolean}){const [stream,setStream]=useState('all'),[search,setSearch]=useState('');const items=operationsFor(job).activities.filter(a=>(stream==='all'||a.stream===stream)&&[a.title,a.sampleId,actor.employees.find(e=>e.id===a.owner)?.name].join(' ').toLowerCase().includes(search.toLowerCase()));return <section className="panel ops-panel"><h2>Assigned laboratory activities</h2><Clarification id="multi-owner"/><div className="settings-filters"><label>Search activity, sample or employee<input value={search} onChange={e=>setSearch(e.target.value)}/></label><label>Workstream<select value={stream} onChange={e=>setStream(e.target.value)}><option value="all">Both workstreams</option><option>PVT</option><option>Chemical</option></select></label></div>{items.some(a=>a.kind==='validation')&&<section><h3>Validation · per sample</h3><p>The sequence follows each sample’s sampling type. Each step has its own owner, dates and workbook.</p>{items.filter(a=>a.kind==='validation').map(a=><ActivityEditor key={a.id} activity={a} actor={actor} run={run}/>)}</section>}{items.some(a=>a.kind!=='validation')&&<section><h3>Analyses and other activities</h3>{items.filter(a=>a.kind!=='validation').map(a=><ActivityEditor key={a.id} activity={a} actor={actor} run={run}/>)}</section>}{!items.length&&<p>No activities match. The scope selector confirms required activities in Scope before the team leads assign them.</p>}</section>;}
