 const entries=(v?:LabScopeVersion):ScopeEntry[]=>(job.samples||[]).map(s=>{const e=v?.samples.find(x=>x.sampleId===s.id);return e?{sampleId:s.id,destination:e.destination,pvtTests:[...e.pvtTests],chemicalTests:[...e.chemicalTests],notes:e.notes,excluded:e.excluded,exclusionReason:e.exclusionReason}:{sampleId:s.id,destination:'PVT',pvtTests:[],chemicalTests:[],notes:'',excluded:false,exclusionReason:''};});
