 const [editing,setEditing]=useState(last?.status==='Draft');const [samples,setSamples]=useState(initial.samples),[conditions,setConditions]=useState(initial.conditions),[reason,setReason]=useState(initial.reason),[review,setReview]=useState(false);
 useUnsaved(editing&&JSON.stringify({samples,conditions,reason})!==JSON.stringify(initial));
 const problems=labScopeProblems(job,samples,conditions,routing,roles,released);
 const update=(id:string,change:Partial<ScopeEntry>)=>{setReview(false);setSamples(list=>list.map(s=>s.sampleId===id?{...s,...change}:s));};
 const listKey=(stream:Stream)=>stream==='PVT'?'pvtTests':'chemicalTests';
 const toggle=(entry:ScopeEntry,stream:Stream,test:string,on:boolean)=>{const key=listKey(stream);update(entry.sampleId,{[key]:on?[...entry[key].filter(t=>t!==test),test]:entry[key].filter(t=>t!==test)});};
 const setUnclassified=(entry:ScopeEntry,test:string,value:string)=>update(entry.sampleId,{pvtTests:[...entry.pvtTests.filter(t=>t!==test),...(value==='PVT'||value==='Both'?[test]:[])],chemicalTests:[...entry.chemicalTests.filter(t=>t!==test),...(value==='Chemical'||value==='Both'?[test]:[])]});
